WITH RECURSIVE t(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM t WHERE n < 5
)
SELECT SUM(n) FROM t;

WITH c AS (SELECT random() AS r)
SELECT c1.r = c2.r
FROM c AS c1, c AS c2;

WITH RECURSIVE t(n) AS (
  SELECT 1
  UNION
  SELECT n % 3 + 1 FROM t
)
SELECT COUNT(*) FROM t;
